// client/src/app/pages/payment/payment.component.ts
import { Component, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, Router } from '@angular/router';
import { OrdersService } from '../../services/orders.service';
import { CartService } from '../../services/cart.service';

@Component({
  standalone: true,
  selector: 'app-payment',
  imports: [CommonModule],
  templateUrl: './payment.component.html',
})
export class PaymentComponent implements OnInit {

  orderId!: number;
  order?: any;
  message = '';
  loading = false;

  constructor(
    private route: ActivatedRoute,
    private orders: OrdersService,
    private router: Router,
    private cart: CartService
  ) {}

  ngOnInit() {
    // Get order ID from route param
    this.orderId = Number(this.route.snapshot.paramMap.get('orderId'));
    this.fetchOrder();
  }

  // Fetch order details from backend
  fetchOrder() {
    this.orders.get(this.orderId).subscribe({
      next: (o) => this.order = o,
      error: () => this.message = 'Failed to load order details'
    });
  }

  // Initiate Stripe payment
  payNow() {
    if (!this.order) return;

    this.loading = true;
    this.orders.createStripeSession(this.orderId).subscribe({
      next: (res) => {
        // Redirect user to Stripe Checkout page
        window.location.href = res.checkout_url;
      },
      error: (err) => {
        this.message = err?.error?.detail || 'Payment failed';
        this.loading = false;
      }
    });
  }

  // Navigate back to orders page
  goOrders() {
    this.router.navigateByUrl('/orders');
  }
}
